import{_ as o,o as t,c as a,a0 as i}from"./chunks/framework.OED5XGjC.js";const g=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),n={name:"explanation/decisions.md"};function r(s,e,c,d,h,l){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the calls that shaped myco, the alternatives rejected, and the consequences we live with. Deeper versions live in the ledger&#39;s own <code>adrs/</code> — this page is the map, not the archive.</p><h2 id="markdown-is-canonical-the-index-is-disposable" tabindex="-1">Markdown is canonical; the index is disposable <a class="header-anchor" href="#markdown-is-canonical-the-index-is-disposable" aria-label="Permalink to &quot;Markdown is canonical; the index is disposable&quot;">​</a></h2><p><strong>Decision:</strong> <code>project/</code> files are the source of truth; the redb index is a derived cache that <code>status</code>/<code>view</code>/<code>org</code> read through and <code>index rebuild</code> regenerates.</p><p><strong>Alternatives:</strong> a database as the store; git as the only read path (no index at all).</p><p><strong>Consequence:</strong> the ledger is human-editable, diffable, and survives index corruption — at the cost that every read pays a snapshot sync and <code>check</code> must reconcile drift between the two.</p><h2 id="an-orphan-branch-worktree-not-files-on-main" tabindex="-1">An orphan branch + worktree, not files on <code>main</code> <a class="header-anchor" href="#an-orphan-branch-worktree-not-files-on-main" aria-label="Permalink to &quot;An orphan branch + worktree, not files on `main`&quot;">​</a></h2><p><strong>Decision:</strong> the ledger lives on a <code>project</code> orphan branch mounted as a <code>project/</code> worktree; code branches gitignore it.</p><p><strong>Alternatives:</strong> ledger files committed on <code>main</code>; a separate repo per ledger; a <code>.myco/</code> dir inside the code tree.</p><p><strong>Consequence:</strong> ledger commits never pollute code history and PRs, and both trees stay checked out at once — but it requires git worktree machinery, and a detached HEAD silently breaks the audit trail (enforced by <code>check</code> + mutating-verb refusal, ADR-0003).</p><h2 id="one-registry-of-verbs-the-prelude-is-config" tabindex="-1">One registry of verbs; the prelude is config <a class="header-anchor" href="#one-registry-of-verbs-the-prelude-is-config" aria-label="Permalink to &quot;One registry of verbs; the prelude is config&quot;">​</a></h2><p><strong>Decision:</strong> mutations are code in one verb registry; what exists — kinds, views, verb aliases — is layered config (<code>myco.toml</code>).</p><p><strong>Alternatives:</strong> per-kind verbs hard-coded; a schema DSL over arbitrary item fields; user-defined mutation logic.</p><p><strong>Consequence:</strong> <code>myco init</code>&#39;s seeded prelude makes PM the default program of a general records engine (P-009), and custom kinds ride the generic surface for free — but mutations can never be redefined by config, which is the point (ADR-0004).</p><h2 id="commit-per-mutation-on-project" tabindex="-1">Commit-per-mutation on <code>project</code> <a class="header-anchor" href="#commit-per-mutation-on-project" aria-label="Permalink to &quot;Commit-per-mutation on `project`&quot;">​</a></h2><p><strong>Decision:</strong> every mutating verb lands as one atomic conventional commit; <code>--no-commit</code>/<code>MYCO_NO_COMMIT</code> batches for scripted flows.</p><p><strong>Alternatives:</strong> write files, commit on demand; a WAL outside git.</p><p><strong>Consequence:</strong> <code>git -C project log</code> <em>is</em> the audit trail — no separate store to keep honest — at the price of one commit per verb (noise is accepted; the branch is orphaned precisely so it doesn&#39;t matter).</p><h2 id="no-cargo-binary-the-command-is-a-tamias-shim" tabindex="-1">No cargo binary; the command is a tamias shim <a class="header-anchor" href="#no-cargo-binary-the-command-is-a-tamias-shim" aria-label="Permalink to &quot;No cargo binary; the command is a tamias shim&quot;">​</a></h2><p><strong>Decision:</strong> <code>myco-cli</code> is lib-only; the <code>myco</code> command ships as a tamias pack whose <code>bins[]</code> shim dispatches <code>cli</code> → the engine.</p><p><strong>Alternatives:</strong> a <code>[[bin]]</code> in <code>myco-cli</code>; crates.io releases.</p><p><strong>Consequence:</strong> install/update lifecycle is tamias&#39;s problem (<code>tamias install 9aia:myco@&lt;ver&gt;</code>), and the engine is drivable in-process by <code>myco-driver</code> — but there is no <code>cargo install myco</code>, and org policy keeps the crates off crates.io.</p><h2 id="git-through-lasius-vcs-not-a-git-library" tabindex="-1">Git through <code>lasius-vcs</code>, not a git library <a class="header-anchor" href="#git-through-lasius-vcs-not-a-git-library" aria-label="Permalink to &quot;Git through `lasius-vcs`, not a git library&quot;">​</a></h2><p><strong>Decision:</strong> all git access goes through the shared <code>lasius-vcs</code> port (git CLI impl) inside <code>myco-ops::vcs</code>.</p><p><strong>Alternatives:</strong> git2/gix bindings; shelling out ad hoc per call.</p><p><strong>Consequence:</strong> one git implementation org-wide, no binding dependency or version drift — at the cost of depending on a <code>git</code> binary on PATH and parsing CLI behavior.</p>',26)])])}const m=o(n,[["render",r]]);export{g as __pageData,m as default};
